// Three audiences, matching the Guide: everybody, admins, and the one account that runs the app.
export const newsFor = (role, adminish, owner) => { const ok = adminish === undefined ? role === 'admin' : !!adminish; return NEWS.filter((n) => n.audience === 'all' || (n.audience === 'admin' && ok) || (n.audience === 'owner' && !!owner)); };
export const latestNewsId = (role, adminish, owner) => (newsFor(role, adminish, owner)[0] || {}).id || '';
